const listProducts = `-- name: ListProducts :many
SELECT p.id, p.key, p.kind, p.name, p.description, p.status,
       v.id AS version_id, v.version, v.status AS version_status,
       COALESCE(ARRAY(
         SELECT m.key::text FROM platform.product_version_modules pvm
         JOIN platform.modules m ON m.id = pvm.module_id
         WHERE pvm.product_version_id = v.id ORDER BY m.sort_order
       ), '{}')::text[] AS modules
FROM platform.products p
JOIN LATERAL (
  SELECT id, created_at, updated_at, product_id, version, status, effective_from, effective_to FROM platform.product_versions pv
  WHERE pv.product_id = p.id AND (NOT $1::boolean OR pv.status = 'published')
  ORDER BY pv.version DESC LIMIT 1
) v ON true
WHERE (NOT $1::boolean OR p.status = 'active')
ORDER BY p.kind, p.name
`

type ListProductsRow struct {
	ID            uuid.UUID
	Key           string
	Kind          string
	Name          string
	Description   string
	Status        string
	VersionID     uuid.UUID
	Version       int32
	VersionStatus string
	Modules       []string
}

func (q *Queries) ListProducts(ctx context.Context, publishedOnly bool) ([]ListProductsRow, error) {
	rows, err := q.db.Query(ctx, listProducts, publishedOnly)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListProductsRow
	for rows.Next() {
		var i ListProductsRow
		if err := rows.Scan(
			&i.ID,
			&i.Key,
			&i.Kind,
			&i.Name,
			&i.Description,
			&i.Status,
			&i.VersionID,
			&i.Version,
			&i.VersionStatus,
			&i.Modules,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

