const upsertEffective = `-- name: UpsertEffective :one
INSERT INTO platform.tenant_module_entitlements (tenant_id, module_id, status, effective_from, effective_until, entitlement_version)
VALUES ($1, $2, $3, $4, $5, 1)
ON CONFLICT (tenant_id, module_id) DO UPDATE
SET status = EXCLUDED.status, effective_from = EXCLUDED.effective_from, effective_until = EXCLUDED.effective_until,
    entitlement_version = platform.tenant_module_entitlements.entitlement_version + 1
RETURNING status, entitlement_version
`

type UpsertEffectiveParams struct {
	TenantID       uuid.UUID
	ModuleID       uuid.UUID
	Status         string
	EffectiveFrom  *time.Time
	EffectiveUntil *time.Time
}

type UpsertEffectiveRow struct {
	Status             string
	EntitlementVersion int64
}

func (q *Queries) UpsertEffective(ctx context.Context, arg UpsertEffectiveParams) (UpsertEffectiveRow, error) {
	row := q.db.QueryRow(ctx, upsertEffective,
		arg.TenantID,
		arg.ModuleID,
		arg.Status,
		arg.EffectiveFrom,
		arg.EffectiveUntil,
	)
	var i UpsertEffectiveRow
	err := row.Scan(&i.Status, &i.EntitlementVersion)
	return i, err
}
